gesiTable = {
  if (!gesiSeries.length) return html`&lt;div style="color:#666;font-style:italic"&gt;No GESI indicators reported for ${county}.&lt;/div&gt;`;
  const W = 220, H = 17, x = (p) =&gt; 6 + p * (W - 12);
  const fmt = (v) =&gt; v == null ? "—" : (Math.abs(v) &gt;= 100 ? Math.round(v).toLocaleString() : +v.toFixed(2));
  // national distribution strip: one grey dot per county, median tick, Kenya
  // diamond, selected county highlighted.
  // faint quartile bands of each indicator's 47-county range (neutral blue —
  // NOT good/bad, since "better" direction varies by indicator).
  const bandFill = ["#eef4fa", "#e1ecf6", "#d3e2f1", "#c4d8ec"];
  const strip = (s) =&gt; {
    const bands = [0, 0.25, 0.5, 0.75].map((b, i) =&gt;
      svg`&lt;rect x=${x(b)} y="1.5" width=${x(b + 0.25) - x(b)} height=${H - 3} fill=${bandFill[i]}/&gt;`);
    const others = s.dots.filter((d) =&gt; !d.sel).map((d) =&gt;
