// break the line across long gaps: FEWS retail series are ~monthly; a jump of
// &gt; ~3 months = missing data, so start a new segment (z) rather than draw a
// straight interpolation across the gap. dots mark every actual observation.
pricesSeg = {
  const GAP_DAYS = 100; // &gt; ~3 months apart =&gt; new segment
  const byMkt = d3.group(pricesCty, (d) =&gt; d.market);
  const out = [];
  for (const [mkt, rows] of byMkt) {
    const sorted = rows
      .map((d) =&gt; ({...d, _t: new Date(d.period_date)}))
      .sort((a, b) =&gt; a._t - b._t);
    let seg = 0;
    for (let i = 0; i &lt; sorted.length; i++) {
      if (i &gt; 0 && (sorted[i]._t - sorted[i - 1]._t) / 86400000 &gt; GAP_DAYS) seg++;
      out.push({...sorted[i], seg: `${mkt}__${seg}`});
    }
  }
  return out;
}







