adaptiveCapacityMap = {
  const t = nbText.GenderInvestments.adaptiveCapacity;
  const { indicator, view } = capMapControls;
  const rows = adaptiveCapacity.filter((d) =&gt; d.indicator === indicator);
  const byIso = d3.rollup(
    rows,
    (g) =&gt; {
      const f = g.find((d) =&gt; d.sex === "F");
      const m = g.find((d) =&gt; d.sex === "M");
      return {
        F: f?.value ?? null,
        M: m?.value ?? null,
        gap: f && m ? +(f.value - m.value).toFixed(1) : null,
        year: f?.year ?? m?.year,
      };
    },
    (d) =&gt; d.iso3n,
  );
  const data = [...byIso].map(([iso3n, v]) =&gt; ({ iso3n, ...v }));
  const features = mergeDataToBoundaries({
    boundaries: africaA0,
    data,
    boundaryKey: "iso3n",
    dataKey: "iso3n",
  });
  const isGap = view === "gap";
  const maxGap = d3.max(data, (d) =&gt; Math.abs(d.gap ?? 0)) || 10;
  const map = makeChoropleth({
    features: features.features,
    width: Math.min(width, 820),
    height: 480,
    fill: (d) =&gt; d.properties.data?.[view] ?? undefined,
    color: isGap
      ? { type: "linear", scheme: "RdBu", domain: [-maxGap, maxGap], unknown: "#e0e0e0", label: t.map.legendGap }
      : { type: "linear", scheme: "YlGnBu", domain: [0, 100], unknown: "#e0e0e0", label: `${t.indicators[indicator]} (%)` },
    channels: {
      country: { label: " ", value: (d) =&gt; countryNameN(d.properties.iso3n) },
      women: { label: t.sexes.F, value: (d) =&gt; d.properties.data?.F },
      men: { label: t.sexes.M, value: (d) =&gt; d.properties.data?.M },
    },
    tooltip: { country: true, women: true, men: true },
    adminHighlight: {
      filter: (d) =&gt; d.properties.iso3n === capCountry,
      stroke: "#111",
      strokeWidth: 2,
    },
  });
  return map;
}







