Data import and cleaning

db = {
  let db = await DuckDBClient.of({
    cv_raw: FileAttachment("/data/economicReturns/faostat_prod_cv.parquet")
  })
  // Exposure denominator: crop + livestock value of production in NOMINAL 2021 USD, per admin1,
  // from the Atlas exposure hub (hazards_prototype 0.4.4 §3.2). Resolution-explicit key since
  // 2026-09-28: `_res-05` is the 0.05° Atlas exposure grid (complete at admin1); the unsuffixed key
  // is a deprecated alias of it. The `unit` column moved from `usd` to `nominal-usd-2021` on that
  // date, so the derived label below reads `vop_nominal-usd-2021` (was `vop_usd`); nothing here
  // filters on it. Values changed on 2026-09-28 where a producer-price defect was corrected
  // (hazards_prototype dispatch 2026-09-27: Zimbabwe wheat, oil palm in East/Central Africa).
  await db.query(`
    CREATE TABLE exposure AS
      SELECT
        iso3,
        admin0_name,
        admin1_name,
        REGEXP_REPLACE(crop, '-tropical|-highland', '') AS crop,
        CONCAT(exposure, '_', unit) AS exposure,
        SUM(value) AS value
      FROM read_parquet("s3://digital-atlas/domain=exposure/type=combined/source=glw4-2020_spam2020AA/region=ssa/processing=atlas-harmonized/variable=vop_nominal-usd-2021_res-05.parquet")
      WHERE
        admin2_name IS NULL AND admin1_name IS NOT NULL
        AND (tech = 'all' OR tech IS NULL)
        AND isfinite(value)
        AND crop !~ '(^other-|rest-of|temperate-fruit|tropical-fruit|vegetables)'
      GROUP BY
        iso3,
        admin0_name,
        admin1_name,
        crop,
        CONCAT(exposure, '_', unit)
  `)
  await db.query(`
    CREATE VIEW cv AS
      SELECT
        admin0_name,
        -- clean and standardize crop names
        REGEXP_REPLACE(
          REGEXP_REPLACE(
            REPLACE(REPLACE(crop, '_meat', ''), ' ', '-'),
            'goat$', 'goats'
          ),
          'pig$', 'pigs'
        ) AS crop,
        value_filled AS cv
      FROM cv_raw
      WHERE NOT (crop ILIKE '%milk%' OR crop ILIKE '%eggs%' OR LOWER(crop) = 'total')

      UNION ALL
      -- add robusta-coffee and small-millet substitutes
      SELECT admin0_name, 'robusta-coffee', value_filled AS cv
      FROM cv_raw
      WHERE crop = 'arabica-coffee'

      UNION ALL
      SELECT admin0_name, 'small-millet', value_filled AS cv
      FROM cv_raw
      WHERE crop = 'pearl-millet';
`)
  return db;
};

