// Per-phase season means, computed live (deterministic aggregation).
phaseChips = {
  if (rainTimeRes.startsWith("Month")) return html``;
  const chips = rainActiveSeasons.flatMap((s) =&gt; {
    const {rows, clim} = rainSeasonData.get(s);
    const isMAM = s === "MAM";
    const groups = isMAM
      ? [{key: "wnp", p: "Western-V high"}, {key: "wnp", p: "Western-V low"}]
      : [{key: "enso", p: "El Niño"}, {key: "enso", p: "La Niña"},
         {key: "iodPhase", p: "IOD positive"}, {key: "iodPhase", p: "IOD negative"}];
    return groups.map(({key, p}) =&gt; {
      const sub = rows.filter((r) =&gt; r[key] === p);
      if (sub.length &lt; 3) return null;
      const m = d3.mean(sub, (r) =&gt; r.value) - (varIsAnom ? 0 : 0);
      const dev = d3.mean(sub, (r) =&gt; r.value) - clim;
      const col = varIsTemp
        ? (dev &gt;= 0 ? PALETTE.impact.bad : "#4575b4")
        : (dev &gt;= 0 ? PALETTE.outcome.wetter : PALETTE.outcome.drier);
      const lbl = varIsSpei ? m.toFixed(2) : `${dev &gt;= 0 ? "+" : ""}${varIsTemp ? dev.toFixed(1) + " °C" : Math.round(dev) + " mm"}`;
      return html`&lt;span style="display:inline-block;margin:2px 8px 2px 0;padding:2px 10px;border:1px solid #ddd;border-radius:12px;font-size:12.5px"&gt;
        ${seasonWord(s)} · ${p}: &lt;b style="color:${col}"&gt;${varIsSpei ? "SPEI " + lbl : lbl + " vs normal"}&lt;/b&gt; &lt;span style="color:#999"&gt;(${sub.length} years)&lt;/span&gt;&lt;/span&gt;`;
    }).filter(Boolean);
  });
  return chips.length ? html`&lt;div style="margin:0.25rem 0"&gt;&lt;span style="font-size:12px;color:#666"&gt;${_lang(nbText.sections.b2.phaseChipsNote)}&lt;/span&gt;&lt;br&gt;${chips}&lt;/div&gt;` : html``;
}







