ndviSwarmPanel = (season) =&gt; {
  const months = season === "OND" ? [10, 11, 12] : [3, 4, 5];
  const driver = season === "OND" ? "ENSO + IOD" : "Western-V (WNP)";
  const def = phaseDefs[driver];
  const zm = zSeries(driver, season);
  const by = d3.rollups(ndviCty.filter((d) =&gt; months.includes(d.month)),
    (v) =&gt; d3.mean(v, (d) =&gt; d.ndvi_pct_normal), (d) =&gt; d.year)
    .map(([year, ndvi]) =&gt; ({year, ndvi, z: zm.get(year) ?? null}))
    .filter((d) =&gt; d.ndvi != null && d.z != null);
  if (by.length &lt; 5) return html`&lt;div style="color:#666;font-style:italic"&gt;Too little NDVI data (${season}).&lt;/div&gt;`;
  const bins = [`Strong ${def.pos}`, `Moderate ${def.pos}`, "Neutral / weak", `Moderate ${def.neg}`, `Strong ${def.neg}`];
  const rows = by.map((d) =&gt; ({...d, bin: swarmBinOf(def, d.z)}));
  return Plot.plot({
    height: 330, width: 460, marginLeft: 55, marginBottom: 60, grid: true,
    x: {domain: bins.filter((b) =&gt; rows.some((r) =&gt; r.bin === b)),
        tickFormat: (b) =&gt; wrapTickLabel(b, 11), label: `${driver.replace(/ \(.*\)$/, "")} state that season`},
    y: {label: "season mean NDVI (% of normal)"},
    marks: [
      Plot.ruleY([100], {stroke: "#555", strokeDasharray: "3"}),
      Plot.dot(rows, {x: "bin", y: "ndvi", fill: (d) =&gt; cardColor(d.z), stroke: "#666", strokeWidth: 0.6, r: 5,
        tip: true, title: (d) =&gt; `${d.year}: ${d.ndvi.toFixed(0)}% of normal · ${categoryOf(driver, d.z)}`}),
      Plot.text(rows, {x: "bin", y: "ndvi", text: (d) =&gt; String(d.year), dx: 15, fontSize: 9, fill: "#555"}),
      Plot.tickY(rows, Plot.groupX({y: "median"}, {x: "bin", y: "ndvi", stroke: "#111", strokeWidth: 2.5})),
    ],
  });
}
swarmBinOf = (def, z) =&gt; {
  const a = Math.abs(z);
  if (a &gt;= Z_BANDS.strong) return `Strong ${z &gt; 0 ? def.pos : def.neg}`;
  if (a &gt;= Z_BANDS.moderate) return `Moderate ${z &gt; 0 ? def.pos : def.neg}`;
  return "Neutral / weak";
}
ndviSwarmRows = (season) =&gt; {
  const months = season === "OND" ? [10, 11, 12] : [3, 4, 5];
