pricesSeg = {
  const GAP_DAYS = 100;
  const sel = new Set(priceMarkets);
  const byMkt = d3.group(pricesCty.filter((d) =&gt; sel.has(d.market)), (d) =&gt; d.market);
  const out = [];
  for (const [mkt, rows] of byMkt) {
    const sorted = rows.map((d) =&gt; ({...d, _t: new Date(d.period_date)})).sort((a, b) =&gt; a._t - b._t);
    let seg = 0;
    for (let i = 0; i &lt; sorted.length; i++) {
      if (i &gt; 0 && (sorted[i]._t - sorted[i - 1]._t) / 86400000 &gt; GAP_DAYS) seg++;
      out.push({...sorted[i], seg: `${mkt}__${seg}`});
    }
  }
  return out;
}

pricesView = {
  if (priceView === "Raw price") return {rows: pricesSeg.map((d) =&gt; ({...d, v: d.value_kes})), label: priceUnitLabel, ref: null};
  if (priceView === "Change vs year earlier") {
    const byMkt = d3.group(pricesSeg, (d) =&gt; d.market);
    const out = [];
    for (const [, rows] of byMkt) {
      const byKey = new Map(rows.map((d) =&gt; [`${d.year}-${d.month}`, d.value_kes]));
      for (const d of rows) {
        const prev = byKey.get(`${d.year - 1}-${d.month}`);
        if (prev != null && prev &gt; 0) out.push({...d, v: (d.value_kes / prev - 1) * 100});
      }
    }
    return {rows: out, label: "% change vs same month a year earlier", ref: 0};
  }
  // Seasonal anomaly: z vs that market's month-of-year climatology.
  const byMkt = d3.group(pricesSeg, (d) =&gt; d.market);
  const out = [];
  for (const [, rows] of byMkt) {
    const clim = d3.rollup(rows, (v) =&gt; ({m: d3.mean(v, (d) =&gt; d.value_kes), s: d3.deviation(v, (d) =&gt; d.value_kes)}), (d) =&gt; d.month);
    for (const d of rows) {
      const c = clim.get(d.month);
      if (c && c.s &gt; 0) out.push({...d, v: (d.value_kes - c.m) / c.s});
    }
  }
  return {rows: out, label: "departure from the usual level for that month (standard deviations)", ref: 0};
}
















