outlookMapOND = {
  const W = 660, H = 580;
  const proj = d3.geoMercator().fitExtent([[8, 8], [W - 8, H - 8]],
    {type: "FeatureCollection", features: kenyaA1});
  const path = d3.geoPath(proj);
  const fillFor = (o) =&gt; {
    if (!o) return "url(#ke-hatch)";
    const strong = o.share &gt;= 0.75;
    if (o.modal === "Wet") return strong ? PALETTE.outcome.wetter : PALETTE.outcome.wetterPale;
    if (o.modal === "Dry") return strong ? PALETTE.outcome.drier : PALETTE.outcome.drierPale;
    return strong ? PALETTE.outcome.near : PALETTE.outcome.nearPale;
  };
  const svgEl = d3.create("svg").attr("viewBox", `0 0 ${W} ${H}`)
    .attr("width", W).attr("style", "max-width:100%;height:auto;")
    .attr("role", "img").attr("aria-label", "Analogue outlook map for the short rains");
  svgEl.append("defs").append("pattern").attr("id", "ke-hatch")
    .attr("width", 6).attr("height", 6).attr("patternUnits", "userSpaceOnUse")
    .attr("patternTransform", "rotate(45)")
    .append("rect").attr("width", 2).attr("height", 6).attr("fill", "#d5d5d0");
  svgEl.selectAll("path.cty").data(kenyaA1).join("path").attr("class", "cty")
    .attr("d", path)
    .attr("fill", (f) =&gt; fillFor(countyOutlookOND.get(+f.properties.gaul1_code)))
    .attr("stroke", (f) =&gt; +f.properties.gaul1_code === selGaul ? "#111" : "#fff")
    .attr("stroke-width", (f) =&gt; +f.properties.gaul1_code === selGaul ? 2.2 : 0.6)
    .append("title").text((f) =&gt; {
      const name = gaulToCounty.get(+f.properties.gaul1_code) ?? f.properties.admin1_name;
      const o = countyOutlookOND.get(+f.properties.gaul1_code);
      if (!o) return `${name}: no baseline (not a county, or no 1991–2020 record)`;
      return `${name}: ${o.counts.Wet} wetter / ${o.counts.Near} near / ${o.counts.Dry} drier across ${o.n} analogue years`;
    });
  svgEl.selectAll("path.cty").filter((f) =&gt; +f.properties.gaul1_code === selGaul).raise();
  const legend = html`&lt;div class="ke-leg2" role="img" aria-label="Outlook legend"&gt;
    &lt;div&gt;&lt;/div&gt;&lt;div style="text-align:center"&gt;drier&lt;/div&gt;&lt;div style="text-align:center"&gt;near-normal&lt;/div&gt;&lt;div style="text-align:center"&gt;wetter&lt;/div&gt;
    &lt;div&gt;most analogues agree&lt;/div&gt;
    &lt;div class="cell" style="background:${PALETTE.outcome.drier}"&gt;&lt;/div&gt;
    &lt;div class="cell" style="background:${PALETTE.outcome.near}"&gt;&lt;/div&gt;
    &lt;div class="cell" style="background:${PALETTE.outcome.wetter}"&gt;&lt;/div&gt;
    &lt;div&gt;leaning only&lt;/div&gt;
    &lt;div class="cell" style="background:${PALETTE.outcome.drierPale}"&gt;&lt;/div&gt;
    &lt;div class="cell" style="background:${PALETTE.outcome.nearPale}"&gt;&lt;/div&gt;
    &lt;div class="cell" style="background:${PALETTE.outcome.wetterPale}"&gt;&lt;/div&gt;
  &lt;/div&gt;
  &lt;div style="font-size:11.5px;color:#666"&gt;hatched = no baseline · based on ${analogueYearsOND.length} analogue years&lt;/div&gt;`;
  return html`&lt;div&gt;${svgEl.node()}${legend}&lt;/div&gt;`;
}







