corrMap = {
  const W = 620, H = 540;
  const data = corrByCounty; // Map gaul -&gt; {r, n, p}
  const proj = d3.geoMercator().fitExtent([[8, 8], [W - 8, H - 8]],
    {type: "FeatureCollection", features: kenyaA1});
  const path = d3.geoPath(proj);
  const color = d3.scaleDiverging([-0.8, 0, 0.8], d3.interpolateBrBG); // + = wetter with +index = teal
  const svgEl = d3.create("svg").attr("viewBox", `0 0 ${W} ${H}`)
    .attr("width", W).attr("style", "max-width:100%;height:auto;")
    .attr("role", "img").attr("aria-label", "County correlation map");
  svgEl.selectAll("path").data(kenyaA1).join("path")
    .attr("d", path)
    .attr("fill", (f) =&gt; {
      const s = data.get(+f.properties.gaul1_code);
      if (!s) return "#f0f0ec";
      return s.p &gt; 0.05 ? "#dcdcd8" : color(s.r);
    })
    .attr("stroke", (f) =&gt; +f.properties.gaul1_code === selGaul ? "#111" : "#fff")
    .attr("stroke-width", (f) =&gt; +f.properties.gaul1_code === selGaul ? 2 : 0.6)
    .append("title").text((f) =&gt; {
      const name = gaulToCounty.get(+f.properties.gaul1_code) ?? f.properties.admin1_name;
      const s = data.get(+f.properties.gaul1_code);
      return s ? `${name}: r = ${s.r.toFixed(2)}, n = ${s.n}, p ${s.p &lt; 0.001 ? "&lt; 0.001" : "= " + s.p.toFixed(3)}${s.p &gt; 0.05 ? " (not significant)" : ""}`
               : `${name}: no data`;
    });
  const legend = Plot.legend({color: {type: "diverging", domain: [-0.8, 0.8],
    interpolate: (t) =&gt; d3.interpolateBrBG(t), label: `correlation r (${corrDriverPick} vs ${corrSeasonPick.includes("OND") ? "OND" : "MAM"} rainfall anomaly)`}, width: 340});
  return html`&lt;div&gt;${svgEl.node()}${legend}
    &lt;div style="font-size:11.5px;color:#666"&gt;grey = not significant at p&lt;0.05 · n = ${d3.min([...data.values()], (s) =&gt; s.n)}–${d3.max([...data.values()], (s) =&gt; s.n)} seasons per county · no multiple-testing correction — read the spatial pattern, not single counties&lt;/div&gt;&lt;/div&gt;`;
}







