tradeMap = {
  const kenC = centroidByIso["KEN"];
  const links = xbtFlows.map((f) =&gt; {
    const c = centroidByIso[f.partner_iso3];
    if (!c || !kenC) return null;
    const imp = f.direction === "Import";
    return {...f, x1: imp ? c[0] : kenC[0], y1: imp ? c[1] : kenC[1],
                  x2: imp ? kenC[0] : c[0], y2: imp ? kenC[1] : c[1]};
  }).filter((d) =&gt; d != null);
  const maxQ = d3.max(links, (d) =&gt; d.qty) || 1;
  const nodes = [...new Set(xbtFlows.map((f) =&gt; f.partner_iso3))]
    .map((iso) =&gt; ({iso, c: centroidByIso[iso]})).filter((d) =&gt; d.c);
  // crop to the trading neighbourhood only (no Madagascar/dead ocean)
  const isoKeep = new Set(["KEN", ...nodes.map((n) =&gt; n.iso)]);
  const domain = {type: "FeatureCollection",
    features: africaFeatures.filter((f) =&gt; isoKeep.has(f.properties.iso3))};
  const wFor = (q) =&gt; 1 + 7 * Math.sqrt(q / maxQ);
  const legQ = [maxQ, maxQ / 4, maxQ / 16];
  const legend = html`&lt;div style="font-size:11.5px;color:#555;margin-top:4px"&gt;arrow width:
    ${legQ.map((q) =&gt; html`&lt;span style="margin-right:14px"&gt;&lt;svg width="46" height="10"&gt;&lt;line x1="2" y1="5" x2="44" y2="5" stroke="#888" stroke-width=${wFor(q)}/&gt;&lt;/svg&gt; ${d3.format("~s")(q)} ${xbtUnit}&lt;/span&gt;`)}&lt;/div&gt;`;
  const chart = Plot.plot({
    projection: {type: "mercator", domain, inset: 24}, width: 760, height: 560,
    color: {domain: ["Import", "Export"], range: ["#d95f0e", "#238b45"], legend: true},
    marks: [
      Plot.geo(domain.features, {stroke: "#d0d0d0", fill: "#f6f6f4"}),
      Plot.geo(domain.features.filter((f) =&gt; f.properties.iso3 === "KEN"), {fill: "#e6efe6", stroke: "#333"}),
      Plot.arrow(links, {x1: "x1", y1: "y1", x2: "x2", y2: "y2", stroke: "direction",
        strokeWidth: (d) =&gt; wFor(d.qty), bend: 18, headLength: 9,
        tip: true, title: (d) =&gt; `${d.direction}: ${d.partner}\n${d3.format(",.0f")(d.qty)} ${d.unit}`}),
      Plot.dot(nodes, {x: (d) =&gt; d.c[0], y: (d) =&gt; d.c[1], r: 3, fill: "#333"}),
      Plot.text(nodes, {x: (d) =&gt; d.c[0], y: (d) =&gt; d.c[1], text: (d) =&gt; d.iso,
        dy: -8, fontWeight: 600, fill: "#333"}),
    ],
  });
  return html`&lt;div&gt;${chart}${legend}&lt;/div&gt;`;
}







