treemapTextLayout = (w, h, labelLen, valueLen, maxBase = 14) =&gt; {
  const availW = Math.max(0, w - 12), availH = Math.max(0, h - 6);
  if (availW &lt; 18 || availH &lt; 12) return {showLabel: false, showValue: false, labelSize: 0, valueSize: 0};
  const fitW = (n) =&gt; availW / Math.max(1, n * 0.55);
  const labelSize = Math.min(fitW(labelLen), availH * 0.55, maxBase);
  const valueSize = Math.min(fitW(valueLen), labelSize * 0.85);
  const MIN = 6.5;
  const showLabel = labelSize &gt;= MIN;
  const showValue = showLabel && valueSize &gt;= MIN && labelSize * 1.3 + valueSize * 1.2 &lt;= availH;
  return {showLabel, showValue, labelSize: Math.round(labelSize * 10) / 10, valueSize: Math.round(valueSize * 10) / 10};
}
