      return {x1, x2, z,
        lbl: `${fmt(new Date(Date.UTC(y, m - 1, 15)))}: ${categoryOf(bgDriver, z)} — ${z.toFixed(1)} sd (measured, 3-month window centred here)`};
    }).filter((d) =&gt; d.x2.getTime() &gt; f && d.x1.getTime() &lt; t)
      // clamp edge rects to the chart's own data window (v2.7 contract) so
      // month blocks never bleed past the frame or inflate an inferred domain
      .map((d) =&gt; ({...d,
        x1: d.x1.getTime() &lt; f ? new Date(f) : d.x1,
        x2: d.x2.getTime() &gt; t ? new Date(t) : d.x2}));
    return [Plot.rect(months, {x1: "x1", x2: "x2", y1: () =&gt; y1, y2: () =&gt; y2,
      fill: (d) =&gt; cardColor(d.z), fillOpacity: 0.85, title: (d) =&gt; d.lbl})];
  }
  if (x === "date") {
    // Discrete: paint ONLY the measured 3-month season windows
    const f = from ? from.getTime() : -Infinity, t = to ? to.getTime() : Infinity;
    const rects = seasons.flatMap((sn) =&gt; {
      const zm = zSeries(bgDriver, sn);
      return [...zm.entries()].map(([year, z]) =&gt; ({
        x1: new Date(Date.UTC(year, sn === "OND" ? 9 : 2, 1)),
        x2: new Date(Date.UTC(year, sn === "OND" ? 12 : 5, 1)), z, year, sn}));
    }).filter((d) =&gt; d.x2.getTime() &gt;= f && d.x1.getTime() &lt;= t);
