      fill: (d) =&gt; bgDiscColor(d.z), fillOpacity: 0.85,
      title: (d) =&gt; `${d.sn} ${d.year}: ${categoryOf(bgDriver, d.z)} — strength ${d.z.toFixed(1)} sd`})];
  }
  // year-x: MAM on the left half of the year slot, OND on the right
  const rects = seasons.flatMap((sn) =&gt; {
    const zm = zSeries(bgDriver, sn);
    return [...zm.entries()]
      .filter(([year]) =&gt; (from == null || year &gt;= from) && (to == null || year &lt;= to))
      .map(([year, z]) =&gt; ({x1: year + (sn === "OND" ? 0.05 : -0.45), x2: year + (sn === "OND" ? 0.45 : -0.05), z, year, sn}));
