    S: v.filter((d) =&gt; d.season === "Short").length}), (d) =&gt; d.crop);
  return [...counts.entries()]
    .filter(([, c]) =&gt; c.L + c.S &gt;= 8)
    .sort((a, b) =&gt; (b[1].L + b[1].S) - (a[1].L + a[1].S))
    .map(([crop, c]) =&gt; ({crop, label: `${crop} — ${c.L} Long / ${c.S} Short seasons on record`}));
}
// era-median anomaly (% of a usual year), qc-clean rows only, gate &gt;=7 yrs
hsRows = {
  const rows = hsSeasonalAll.filter((d) =&gt; d.crop === hsCrop.crop);
  // each variable gets its own era median, gated on ITS OWN qc-clean non-null rows
  const eras = d3.group(rows.filter((d) =&gt; d.qc === 0), (d) =&gt; d.season + "|" + hsEraOf(d.py));
  const med = new Map();
  for (const [k, v] of eras) {
    for (const col of ["yield_t_ha", "production_t", "area_ha"]) {
      const vv = v.filter((d) =&gt; d[col] != null);
      med.set(k + "|" + col, vv.length &gt;= 7 ? d3.median(vv, (d) =&gt; d[col]) : null);
    }
  }
  const varKey = hsVar.id;
  const tOnd = tercByYear("OND"), tMam = tercByYear("MAM");
  return rows.map((d) =&gt; {
    const m = med.get(d.season + "|" + hsEraOf(d.py) + "|" + varKey);
    const val = d[hsVar.id];
    return {...d, era: hsEraOf(d.py),
      value: val,
      anomPct: (m && val != null) ? (val / m) * 100 : null,
      terc: (d.season === "Short" ? tOnd : tMam).get(d.py) ?? null};
