plotTableFmt = (v) =&gt; {
  if (v == null || v === "") return "";
  if (typeof v === "number" && isFinite(v))
    return v.toLocaleString("en-US", {maximumFractionDigits: 2});
  return String(v);
}

plotTableMetaLines = (opts) =&gt; {
  const m = (opts && opts.meta) || {};
  const lines = [
    "# AAA Atlas — ENSO Explorer (Kenya) v2",
    `# Figure: ${(opts && opts.fig) ? opts.fig + " — " : ""}${(opts && opts.filename) || "figure"}`,
    `# Generated: ${new Date().toISOString().slice(0, 10)}`,
  ];
  for (const [k, v] of Object.entries(m)) if (v != null && v !== "") lines.push(`# ${k}: ${v}`);
  return lines;
}

plotDataTable = (opts) =&gt; {
  const data = (opts && opts.data) || [];
  if (!Array.isArray(data) || !data.length) return "";
  const cols = (opts && opts.columns) ||
    Object.keys(data[0]).filter((k) =&gt; !k.startsWith("_"))
      .map((k) =&gt; ({key: k, label: k}));
  const table = html`&lt;table class="plot-data-table"&gt;
    &lt;thead&gt;&lt;tr&gt;${cols.map((c) =&gt; html`&lt;th&gt;${c.label}&lt;/th&gt;`)}&lt;/tr&gt;&lt;/thead&gt;
    &lt;tbody&gt;${data.map((row) =&gt; html`&lt;tr&gt;${cols.map((c) =&gt;
      html`&lt;td&gt;${(c.fmt || plotTableFmt)(row[c.key], row)}&lt;/td&gt;`)}&lt;/tr&gt;`)}&lt;/tbody&gt;
  &lt;/table&gt;`;
  const onDownload = () =&gt; {
    const header = cols.map((c) =&gt; c.label).join(",");
    const esc = (v) =&gt; {
      const s = v == null ? "" : String(v);
      return /[",\n\r]/.test(s) ? '"' + s.split('"').join('""') + '"' : s;
    };
    const body = data.map((row) =&gt; cols.map((c) =&gt; esc(
      (c.fmt || plotTableFmt)(row[c.key], row))).join(",")).join("\r\n");
    const csv = plotTableMetaLines(opts).join("\r\n") + "\r\n\r\n" + header + "\r\n" + body;
    const blob = new Blob(["﻿", csv], {type: "text/csv;charset=utf-8"});
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = ((opts && opts.filename) || "table") + "_table.csv";
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };
  const dlBtn = html`&lt;button class="plot-table-dl" type="button"&gt;⤓ Download table (CSV + metadata)&lt;/button&gt;`;
  dlBtn.onclick = onDownload;
  return html`&lt;details class="plot-caption-details"&gt;
    &lt;summary&gt;Show data table (${data.length} rows)&lt;/summary&gt;
    &lt;div class="plot-caption-body"&gt;${dlBtn}&lt;div class="plot-data-table-wrap"&gt;${table}&lt;/div&gt;&lt;/div&gt;
  &lt;/details&gt;`;
}

plotFooter = (caption, chart, opts) =&gt; {
  const o = opts || {};
  const figPrefix = o.fig ? `**Figure ${o.fig}** — ` : "";
  // About sits ON THE SAME ROW as the download button (Pete P5, CR pattern)
  const about = o.about
    ? html`&lt;details class="plot-caption-details"&gt;
        &lt;summary&gt;About this plot&lt;/summary&gt;
        &lt;div class="plot-caption-body"&gt;${md`${o.about}`}&lt;/div&gt;
      &lt;/details&gt;`
    : "";
  const dlOpts = o.columns ? {...o, csvColumns: o.columns.map((c) =&gt; c.key)} : o;
  return html`&lt;div class="plot-footer"&gt;
    &lt;div class="plot-caption"&gt;${md`${figPrefix}${caption}`}&lt;/div&gt;
    &lt;div class="plot-footer-row"&gt;${chartDownloadButton(chart, dlOpts)}${about}&lt;/div&gt;
    ${o.showTable === false ? "" : plotDataTable(o)}
  &lt;/div&gt;`;
}






























