// redesigned season panel: outcome-filled bars + phase strip lanes below.
rainPanel = (s) =&gt; {
  const {rows, clim} = rainSeasonData.get(s);
  if (!rows.length) return html`&lt;div style="color:#666;font-style:italic"&gt;No ${varDef.v} data for ${county} (${s}).&lt;/div&gt;`;
  const anomaly = varIsSpei ? true : rainView.startsWith("Anomaly");
  const data = rows.map((r) =&gt; ({...r,
    y: varIsSpei ? r.value : (anomaly ? r.value - clim : r.value),
    wet: varIsSpei ? r.value &gt;= 0 : r.value &gt;= clim}));
  const twoUp = rainActiveSeasons.length &gt; 1;
  const W = twoUp ? 440 : 900;
  const yrExtent = d3.extent(data, (d) =&gt; d.year);
  // band scales need the FULL year list, not an extent pair (R2 fix)
  const yrDomain = d3.range(yrExtent[0], yrExtent[1] + 1);
  // per-variable outcome semantics: hotter is NOT "wetter/better" (R2 fix)
  const outcomeDomain = varIsTemp ? ["warmer than normal", "cooler than normal"]
    : ["wetter than normal", "drier than normal"];
  const outcomeRange = varIsTemp ? [PALETTE.impact.bad, "#4575b4"]
    : [PALETTE.outcome.wetter, PALETTE.outcome.drier];
  const outcomeOf = (d) =&gt; varIsTemp
    ? (d.wet ? "warmer than normal" : "cooler than normal")
    : (d.wet ? "wetter than normal" : "drier than normal");
  const yLabel = varIsSpei ? "SPEI-3 (standardised)"
    : varIsTemp ? (anomaly ? "°C vs 1991–2020" : "°C")
    : (anomaly ? "mm vs 1991–2020" : "mm");
  const evYears = namedEvents.filter((e) =&gt; e.seasons.some((x) =&gt; x.startsWith(s + "-")))
    .map((e) =&gt; ({year: +e.seasons.find((x) =&gt; x.startsWith(s + "-")).split("-")[1], label: e.label.en}));
  const hasStrip = s !== "annual";
  const spreadK = spreadOpt.startsWith("±1") ? 1 : spreadOpt.startsWith("±2") ? 2 : 0;
  const spreadMarks = (spreadK &gt; 0 && !varIsSpei)
    ? [Plot.ruleX(data.filter((d) =&gt; d.sd != null), {x: "year",
        y1: (d) =&gt; (!anomaly && !varIsTemp) ? Math.max(0, d.y - spreadK * d.sd) : d.y - spreadK * d.sd,
        y2: (d) =&gt; d.y + spreadK * d.sd, stroke: "#333", strokeWidth: 1,
        title: (d) =&gt; `±${spreadK} sd across the county's pixels (sd = ${varIsTemp ? d.sd.toFixed(1) : Math.round(d.sd)} ${varDef.unit})`})]
    : [];
  const main = Plot.plot({
    height: 330, width: W, marginLeft: 55, marginRight: 20, marginBottom: hasStrip ? 4 : 34,
    // when the phase strip is shown it carries the shared year axis (P13)
    x: {domain: yrDomain, axis: hasStrip ? null : "bottom",
        tickFormat: (d) =&gt; "'" + String(d).slice(-2), label: null, nice: false,
        ticks: data.map((d) =&gt; d.year).filter((y) =&gt; y % 5 === 0)},
    y: {label: yLabel},
    color: {domain: outcomeDomain,
      range: outcomeRange, legend: !twoUp || s === "OND"},
    marks: [
      Plot.barY(data, {x: "year", y: "y", fill: outcomeOf,
