    raw: laneRaw.get(l.lane)?.get(d.year) ?? null})));
  const laneColor = new Map(lanes.flatMap((l) =&gt; l.domain.map((ph, i) =&gt; [ph, l.range[i]])));
  const strip = Plot.plot({
    // the strip carries the shared visible year axis (P13)
    height: 30 + lanes.length * 16, width: W, marginLeft: 55, marginRight: 20, marginTop: 0, marginBottom: 24,
    x: {domain: yrDomain, tickFormat: (d) =&gt; "'" + String(d).slice(-2), label: null, nice: false,
