    marks: [
      Plot.cell(laneRows, {x: "year", y: "lane",
        fill: (d) =&gt; continuous ? cardColor(d.zScaled) : (laneColor.get(d.ph) ?? "#e8e8e4"), inset: 0.5,
        tip: true, title: (d) =&gt; {
          const raw = d.raw == null ? "" : `${laneRawName[d.lane]} ${d.raw &gt;= 0 ? "+" : ""}${d.raw.toFixed(2)} · `;
          return continuous
            ? `${d.year} ${d.lane}: ${raw}${d.z == null ? "no data" : categoryOf(laneDriver[d.lane], d.z) + " (" + d.z.toFixed(1) + " sd)"}`
            : `${d.year} ${d.lane}: ${raw}${d.ph}`;
        }}),
    ],
  });
  const stripLegend = continuous
    ? html`&lt;div style="font-size:10.5px;color:#666;margin-left:55px"&gt;strip colour (each row scaled to its own record): &lt;span style="display:inline-block;width:110px;height:11px;vertical-align:middle;background:linear-gradient(to right, ${cardColor(-2)}, ${cardColor(0)}, ${cardColor(2)})"&gt;&lt;/span&gt; negative ← strength → positive · the strips read the ocean state behind each season — hover any cell for the raw value&lt;/div&gt;`
    : html`&lt;div style="font-size:10.5px;color:#666;margin-left:55px"&gt;${lanes.flatMap((l) =&gt;
        l.domain.filter((ph) =&gt; ph !== "Neutral").map((ph) =&gt;
          html`&lt;span style="margin-right:10px"&gt;&lt;span style="display:inline-block;width:9px;height:9px;background:${laneColor.get(ph)};border-radius:2px"&gt;&lt;/span&gt; ${ph}&lt;/span&gt;`))}&lt;/div&gt;`;
  return html`&lt;div&gt;&lt;div class="ke-panel-lbl"&gt;${seasonWord(s)} (${s})${varIsSpei ? " — drought index" : ""}&lt;/div&gt;${main}${strip}${stripLegend}&lt;/div&gt;`;
}







