// exact null for the MODAL tercile count of n seasons under equal thirds:
// enumerate multinomial(n, 1/3) outcomes (n &lt;= ~50, trivial) — no typed stats.
modalNull = (n) =&gt; {
  const logFact = [0];
  for (let i = 1; i &lt;= n; i++) logFact[i] = logFact[i - 1] + Math.log(i);
  let expMax = 0;
  const pMaxGE = new Array(n + 2).fill(0);
  for (let a = 0; a &lt;= n; a++) for (let b = 0; b &lt;= n - a; b++) {
    const c = n - a - b;
    const pr = Math.exp(logFact[n] - logFact[a] - logFact[b] - logFact[c] - n * Math.log(3));
    const mx = Math.max(a, b, c);
    expMax += mx * pr;
    for (let k = 0; k &lt;= mx; k++) pMaxGE[k] += pr;
  }
  return {expMax, pGE: (k) =&gt; pMaxGE[Math.min(k, n + 1)] ?? 0};
}



















































// IOD-conditioned analogues for the off-diagonal guard (selected county only)
