  return {counts, n, modal, share: n ? counts[modal] / n : 0, sameEnso};
}







// how today's indices sit in the historical OND record (V2-50) — computed,
// never typed; IOD shown alongside ENSO (it carries more OND signal)
stateContextLine = {
  const pctOf = (m, v) =&gt; {
    const vals = [...m.values()].sort((a, b) =&gt; a - b);
    if (!vals.length || v == null) return null;
    return Math.round(100 * d3.bisectLeft(vals, v) / vals.length);
  };
  const pOni = pctOf(roniRawOnd, currentState.oni);
  const pIod = pctOf(iodRawOnd, currentState.dmi);
  const bits = [];
  if (pOni != null) bits.push(`today's ENSO state sits above ${pOni}% of past short-rains seasons`);
  if (pIod != null) bits.push(`today's IOD (the stronger short-rains signal) above ${pIod}%`);
  return bits.length ? "Where today sits in the record: " + bits.join("; ") + "." : "";
}







