// county contingency: OND terciles by ENSO phase + MAM terciles by W-V phase
countyContingency = {
  const rows = outlookBase.filter((r) =&gt; r.gaul1_code === selGaul);
  if (!rows.length) return [];
  const out = [];
  const push = (group, sub) =&gt; {
    const total = sub.length;
    if (total &lt; 5) return;
    for (const t of ["Wet", "Near", "Dry"]) {
      const count = sub.filter((r) =&gt; r.tercile === t).length;
      out.push({group, outcome: t === "Wet" ? "Wetter" : t === "Near" ? "Near-normal" : "Drier",
        count, total, share: count / total});
    }
  };
  // "All years" rows carry each season's own base rate — terciles were
  // defined on 1991-2020, so marginals need not be 1/3 (R2 fix): compare
  // each phase row against the base-rate row, not a perfect-thirds ideal.
  const ond = rows.filter((r) =&gt; r.season === "OND");
  push("Short rains · All years", ond);
  for (const ph of ["El Niño", "Neutral", "La Niña"])
