  ...prodProdNatl.map((d) =&gt; [`Products|${d.item}|${d.year}`, d.natl]),
])
// option objects for the multiselect: {group, item, label}
prodItemsAvail = {
  const inGroups = prodAll.filter((d) =&gt; prodGroups.includes(d.group));
  const seen = new Map();
  for (const d of inGroups) seen.set(`${d.group}|${d.item}`, {group: d.group, item: d.item, label: `${d.item} · ${d.group.toLowerCase().replace(/s$/, "")}`});
  return [...seen.values()].sort((a, b) =&gt; a.group.localeCompare(b.group) || a.item.localeCompare(b.item));
}
prodDefaultPick = {
  // per-group top-6 by latest-year value keeps the default legible
  const picks = [];
  for (const g of prodGroups) {
    const rows = prodAll.filter((d) =&gt; d.group === g && d.val &gt; 0);
    if (!rows.length) continue;
    const latest = d3.max(rows, (d) =&gt; d.year);
    const byItem = d3.rollup(rows.filter((d) =&gt; d.year === latest), (v) =&gt; d3.sum(v, (d) =&gt; d.val), (d) =&gt; d.item);
    const top = [...byItem].sort((a, b) =&gt; b[1] - a[1]).slice(0, 6).map((e) =&gt; e[0]);
    picks.push(...prodItemsAvail.filter((o) =&gt; o.group === g && top.includes(o.item)));
  }
  return picks;
}
prodPctFmt = (v) =&gt; v == null ? null : v === 0 ? 0 : v &gt;= 1 ? +v.toFixed(1) : +v.toPrecision(2)
prodRows = {
