prodFmtVal = (v) =&gt; prodMode.startsWith("%") ? prodPctFmt(v) + "%" : formatNumCompactShort()(v)
prodGroupsShown = () =&gt; [...new Set(prodRows.map((d) =&gt; d.group))]

// Bars: side-by-side years within each commodity (variant-B composite x),
// one panel per commodity group (units differ)
prodViewBars = () =&gt; {
  if (!prodRows.length) return noDataPlaceholder();
  const years = [...new Set(prodRows.map((d) =&gt; d.year))].sort((a, b) =&gt; a - b);
  const yearColor = new Map(years.map((y, i) =&gt; [y, paletteRange(Math.max(years.length, 3))[i]]));
