      .sort((a, b) =&gt; d3.sum(rows.filter((r) =&gt; r.item === b), (r) =&gt; r.value) - d3.sum(rows.filter((r) =&gt; r.item === a), (r) =&gt; r.value));
    const present = new Set(rows.map((d) =&gt; `${d.item}|${d.year}`));
    const xDomain = items.flatMap((it, i) =&gt; {
      const cats = years.filter((y) =&gt; present.has(`${it}|${y}`)).map((y) =&gt; `${it}|${y}`);
      if (i &lt; items.length - 1) cats.push(`__sep_${i}`);
      return cats;
    });
    const midYear = (it) =&gt; {
      const ys = years.filter((y) =&gt; present.has(`${it}|${y}`));
      return ys[Math.floor((ys.length - 1) / 2)];
    };
    const labelTicks = xDomain.filter((k) =&gt; {
      if (!k || k.startsWith("__")) return false;
      const [it, y] = k.split("|");
      return midYear(it) === +y;
    });
    const plot = Plot.plot({
