// Treemap: single-year snapshot (END year, with ≤year fallback per item)
prodViewTree = () =&gt; {
  if (!prodRows.length) return noDataPlaceholder();
  const yEnd = Math.max(prodYearFrom, prodYearTo);
  const groups = prodGroupsShown();
  const cellW = Math.floor((900 - 12 * (groups.length - 1)) / groups.length);
  const tipHost = html`&lt;div class="cr-treemap-tip" role="tooltip"&gt;&lt;/div&gt;`;
  const buildOne = (g) =&gt; {
    const byItem = d3.group(prodRows.filter((d) =&gt; d.group === g), (d) =&gt; d.item);
    const snapshot = [];
    for (const [, rows] of byItem) {
      const valid = rows.filter((r) =&gt; r.year &lt;= yEnd && r.val &gt; 0).sort((a, b) =&gt; b.year - a.year);
      if (valid.length) snapshot.push(valid[0]);
    }
    if (!snapshot.length) return html`&lt;div&gt;&lt;/div&gt;`;
    const items = snapshot.map((d) =&gt; d.item);
    const colorBy = new Map(items.map((it, i) =&gt; [it, paletteRange(items.length)[i]]));
    // treemap AREA is always the absolute value (share of the group total),
    // whatever the Units toggle shows elsewhere — the tooltip carries the %
    const root = d3.hierarchy({children: snapshot}).sum((d) =&gt; d.val).sort((a, b) =&gt; b.value - a.value);
    d3.treemap().size([cellW, 300]).paddingInner(2)(root);
    const groupTotal = root.value || 1;
    const leafEls = root.leaves().map((leaf) =&gt; {
      const w = leaf.x1 - leaf.x0, h = leaf.y1 - leaf.y0;
      const fill = colorBy.get(leaf.data.item) || "#999";
      const valueText = formatNumCompactShort()(leaf.data.val) + " " + leaf.data.unit;
      const tipText = `${leaf.data.item} (${leaf.data.year}): ${valueText} · ${(100 * leaf.value / groupTotal).toFixed(1)}% of shown ${g.toLowerCase()}`;
      const textFill = treemapTextColor(fill);
      const halo = textFill === "#fff" ? "#000" : "#fff";
      const lay = treemapTextLayout(w, h, leaf.data.item.length, valueText.length, 14);
      return svg`&lt;g transform="translate(${leaf.x0}, ${leaf.y0})"&gt;
        &lt;rect class="cr-treemap-cell" data-tip="${tipText}" width="${w}" height="${h}" fill="${fill}" stroke="#999" stroke-width="0.75"&gt;&lt;title&gt;${tipText}&lt;/title&gt;&lt;/rect&gt;
        ${lay.showLabel ? svg`&lt;text x="6" y="${lay.labelSize + 2}" fill="${textFill}" stroke="${halo}" stroke-width="${Math.max(0.8, lay.labelSize * 0.12)}" stroke-opacity="0.6" paint-order="stroke" style="font-size:${lay.labelSize}px;pointer-events:none"&gt;${leaf.data.item}&lt;/text&gt;` : svg`&lt;g/&gt;`}
        ${lay.showValue ? svg`&lt;text x="6" y="${lay.labelSize + 2 + lay.valueSize + 3}" fill="${textFill}" stroke="${halo}" stroke-width="${Math.max(0.7, lay.valueSize * 0.1)}" stroke-opacity="0.5" paint-order="stroke" style="font-size:${lay.valueSize}px;pointer-events:none"&gt;${valueText}&lt;/text&gt;` : svg`&lt;g/&gt;`}
      &lt;/g&gt;`;
    });
    const svgEl = svg`&lt;svg width="${cellW}" height="300" style="display:block;background:#fafafa"&gt;${leafEls}&lt;/svg&gt;`;
    return html`&lt;div style="display:inline-block;vertical-align:top"&gt;
      &lt;div style="font-size:11.5px;color:#444;text-align:center;height:20px;line-height:20px"&gt;${g} — ${yEnd} (or latest ≤ ${yEnd})&lt;/div&gt;${svgEl}&lt;/div&gt;`;
  };
  const grid = html`&lt;div style="display:flex;flex-wrap:wrap;align-items:flex-start;gap:12px"&gt;${groups.map(buildOne)}&lt;/div&gt;`;
  const wrap = html`&lt;div&gt;${tipHost}${grid}&lt;/div&gt;`;
  wrap.querySelectorAll(".cr-treemap-cell").forEach((r) =&gt; {
    const t = r.getAttribute("data-tip");
    r.addEventListener("mouseenter", () =&gt; { tipHost.textContent = t; tipHost.style.display = "block"; });
    r.addEventListener("mousemove", (e) =&gt; { tipHost.style.left = `${e.clientX + 14}px`; tipHost.style.top = `${e.clientY + 14}px`; });
