pearson = (rows, a, b) =&gt; { const A = rows.map((d) =&gt; d[a]), B = rows.map((d) =&gt; d[b]), n = rows.length,
  mA = d3.mean(A), mB = d3.mean(B);
  return d3.sum(A.map((x, i) =&gt; (x - mA) * (B[i] - mB))) / Math.sqrt(d3.sum(A.map((x) =&gt; (x - mA) ** 2)) * d3.sum(B.map((x) =&gt; (x - mB) ** 2))); }
ensoIod = {
  const e = new Map(seasMean([10, 11, 12], "nino34_anom_noaa").map((d) =&gt; [d.year, d.v]));
  const i = seasMean([10, 11, 12], "dmi_hadisst");
  return i.filter((d) =&gt; e.has(d.year)).map((d) =&gt; ({year: d.year, enso: e.get(d.year), iod: d.v}));
}
ensoIodR = pearson(ensoIod, "enso", "iod")
ensoWnp = {
  const e = new Map(seasMean([3, 4, 5], "nino34_anom_noaa").map((d) =&gt; [d.year, d.v]));
  const w = seasMean([3, 4, 5], "wnp_std_mam");
  return w.filter((d) =&gt; e.has(d.year)).map((d) =&gt; ({year: d.year, enso: e.get(d.year), wnp: d.v}));
}
ensoWnpR = pearson(ensoWnp, "enso", "wnp")
zscore = (rows, col) =&gt; { const v = rows.filter((d) =&gt; d.year &gt;= 1991 && d.year &lt;= 2020).map((d) =&gt; d[col]).filter((x) =&gt; x != null);
  const m = d3.mean(v), s = d3.deviation(v); return (d) =&gt; d[col] == null ? null : (d[col] - m) / s; }
combined = {
  const zE = zscore(drivers, "nino34_anom_noaa"), zI = zscore(driversCoal, "dmi"), zW = zscore(drivers, "wnp_std_mam");
  const rows = driversCoal.filter((d) =&gt; d.year &gt;= 2010).flatMap((d) =&gt; [
    {date: new Date(d.date), driver: "ENSO (Niño 3.4)", z: zE(d)},
    {date: new Date(d.date), driver: "IOD (DMI)", z: zI(d)},
    {date: new Date(d.date), driver: "Western-V (WNP)", z: zW(d)}]);
  return rows.filter((d) =&gt; d.z != null);
}


























































tApproxP = (t, df) =&gt; {
  const z = Math.abs(t) * (1 - 1 / (4 * df)) / Math.sqrt(1 + (t * t) / (2 * df));
  const p = 2 * (1 - 0.5 * (1 + erf(z / Math.SQRT2)));
  return Math.max(1e-6, Math.min(1, p));
}
erf = (x) =&gt; {
  const s = x &lt; 0 ? -1 : 1; x = Math.abs(x);
  const a1 = 0.254829592, a2 = -0.284496736, a3 = 1.421413741, a4 = -1.453152027, a5 = 1.061405429, p = 0.3275911;
  const t = 1 / (1 + p * x);
  const y = 1 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * Math.exp(-x * x);
  return s * y;
}
corrSeasonCode = corrSeasonPick.includes("OND") ? "OND" : "MAM"
corrByCounty = {
  const wnpByYear = new Map(seasMean([3, 4, 5], "wnp_std_mam").map((d) =&gt; [d.year, d.v]));
  const driverOf = (r) =&gt; corrDriverPick.startsWith("ENSO") ? r.roni_conc
    : corrDriverPick.startsWith("IOD") ? r.dmi_conc
    : (wnpByYear.get(r.year) ?? null);
  const byCty = d3.group(outlookBase.filter((r) =&gt; r.season === corrSeasonCode), (r) =&gt; r.gaul1_code);
  const out = new Map();
  for (const [gaul, rows] of byCty) {
    const pts = rows.map((r) =&gt; ({x: driverOf(r), y: r.anomaly_pct}))
      .filter((d) =&gt; d.x != null && d.y != null);
    if (pts.length &lt; 20) continue;
    const r = pearson(pts, "x", "y");
    const n = pts.length;
    const t = r * Math.sqrt((n - 2) / (1 - r * r));
    out.set(+gaul, {r, n, p: tApproxP(t, n - 2)});
  }
  return out;
}
corrExport = counties.map((c) =&gt; {
  const s = corrByCounty.get(+c.gaul1_code);
  return {county: c.county, season: corrSeasonCode, driver: corrDriverPick,
    r: s ? +s.r.toFixed(3) : null, n: s ? s.n : null, p: s ? +s.p.toFixed(4) : null};
})





































dotCropList = [...new Set(naprCty.map((d) =&gt; d.item))].sort()
dotPlotRows = {
  const prod = naprCty.filter((d) =&gt; d.item === dotCrop && d.val &gt; 0);
  if (prod.length &lt; 3) return [];
  const med = d3.median(prod, (d) =&gt; d.val);
  // season window: the SELECTED crop's calendar where present, else the
  // county-level rule, else annual (R2 fix — was county-wide only)
  const cropNorm = (x) =&gt; String(x).toLowerCase().replace(/[^a-z]/g, "");
  const own = calCty.filter((r) =&gt; r.stage === "Planting" &&
    (cropNorm(r.crop).includes(cropNorm(dotCrop)) || cropNorm(dotCrop).includes(cropNorm(r.crop))));
  const calRows = own.length ? own : calCty.filter((r) =&gt; r.stage === "Planting");
  const period = calRows.some((r) =&gt; r.season === "Short rains") && !calRows.some((r) =&gt; r.season === "Long rains")
    ? "OND"
    : calRows.some((r) =&gt; r.season === "Long rains") && !calRows.some((r) =&gt; r.season === "Short rains")
    ? "MAM" : "annual";
  const series = chirpsYearlyAll.filter((d) =&gt; d.period === period && d.value != null);
  const sorted = series.map((d) =&gt; d.value).sort((a, b) =&gt; a - b);
  const pctOf = (v) =&gt; sorted.length ? (d3.bisectLeft(sorted, v) / sorted.length) * 100 : null;
  const byYear = new Map(series.map((d) =&gt; [d.year, d.value]));
  return prod.map((d) =&gt; {
    const rain = byYear.get(d.year);
    return rain == null ? null : {year: d.year, rainPct: pctOf(rain), prodPct: d.val / med * 100, period};
  }).filter(Boolean);
}

