`)

vopSummary = {
  const total = d3.sum(vopCty, d =&gt; d.vop_intld15) || 1;
  const livestock = d3.sum(vopCty.filter(d =&gt; d.kind === "Livestock"), d =&gt; d.vop_intld15) || 0;
  const crops = d3.sum(vopCty.filter(d =&gt; d.kind === "Crop"), d =&gt; d.vop_intld15) || 0;
  return {
    total,
    livestock,
    crops,
    pctLivestock: (livestock / total) * 100,
    pctCrops: (crops / total) * 100,
    topLivestock: vopCty.filter(d =&gt; d.kind === "Livestock").slice(0, 4),
    topCrops: vopCty.filter(d =&gt; d.kind === "Crop").slice(0, 4)
  };
}

